import {PARTY,DEFAULT_STATE,ENCOUNTERS,runAll,rollScenario} from './engine.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const dims=[['Damage urgency',88],['Healing delay',86],['Item hoarding',90],['Follow-up spending',82],['Target focus',91],['Juice awareness',8],['Emotion awareness',9],['Speed-order awareness',7]];
const assumptions={spaceboy:['Enemy HP/Attack/Defense/Speed and skill formulas come from OmoriSource RPG Maker data.','The boss action list is evaluated as sequential priority checks, matching its AI note order.','Angry phase thresholds are 75%, 50%, and 25% HP; tier stat effects are modeled.','Follow-ups use first-tier effects; animation timing and presentation-only effects are omitted.'],download:['600 HP, 210 Juice, 10 Attack, 5 Defense, 1 Speed, and 10 Luck come from Enemies.json.','CRASH deals a fixed 80% of each party member’s max HP and cannot miss.','The boss idles on turns 1–2, crashes on 3, idles on 4–5, then crashes every turn.'],bunnies:['Each bunny has 105 HP, 12 Attack, 7 Defense, and 10 Speed.','AI checks Attack at 55%, then Do Nothing at 35%, then Bunny Beam as fallback.','This formation is a testing sample, not a claim about one exact map troop.']};
const invText={standard:'6 Candy · 3 Apple Juice · 2 Life Jam',lean:'2 Candy · 1 Apple Juice · 1 Life Jam',none:'No consumables'};
let current=null;

function pct(r){const v=r.rate*100;if(v===100)return'100%';if(v>99.9)return`${v.toFixed(3)}%`;return`${v.toFixed(1)}%`}
function renderResults(results){$('#results').innerHTML=results.map(r=>`<article class="result ${r.key==='custom'?'custom':''}"><div class="name"><span>${r.name}</span><span>${r.key==='best'?'heuristic':r.key==='custom'?'profile':'policy'}</span></div><div class="win">${pct(r)}</div><div class="ci">${(r.ci[0]*100).toFixed(1)}–${(r.ci[1]*100).toFixed(1)}% · ${r.trials-r.wins} losses</div><div class="bar"><i style="width:${r.rate*100}%"></i></div><div class="metrics"><span>${r.medianTurns} median turns</span><span>${r.avgSurvivors.toFixed(1)} alive</span></div></article>`).join('')}
function updateProbabilityTicks(){const custom=current?.find(r=>r.key==='custom'),best=current?.find(r=>r.key==='best');let values=[.4,.5,.6];if(custom&&best){const optimistic=best.rate,gap=Math.max(.05,optimistic-custom.rate),pessimistic=custom.rate-gap;values=[pessimistic,custom.rate,optimistic]}$('.probability-ticks').classList.toggle('crowded',values[2]-values[0]<.15);[['pessTick','Pessimistic',values[0]],['customTick','Custom',values[1]],['optimTick','Optimistic',values[2]]].forEach(([id,label,rate])=>{const b=$(`#${id}`),v=Math.max(.001,Math.min(.999,rate))*100;b.style.left=`${v}%`;b.dataset.value=v;b.querySelector('span').textContent=label;b.querySelector('strong').textContent=`${v.toFixed(1)}%`;b.onclick=()=>{$('#belief').value=v;updateKelly()}})}
function renderBetReferences(){updateProbabilityTicks();if(!current?.length){$('#betReferences').innerHTML='<span class="muted">Run the battle simulation to populate references.</span>';return}$('#betReferences').innerHTML=current.map(r=>`<button data-rate="${r.rate}"><span>${r.name}</span><strong>${pct(r)}</strong></button>`).join('');$$('#betReferences button').forEach(b=>b.onclick=()=>{$('#belief').value=(Math.max(.001,Math.min(.999,+b.dataset.rate))*100).toFixed(1);updateKelly()})}
function growthFor(stake,bankroll,p,ownPool,otherPool){if(stake<=0)return 0;if(stake>=bankroll)return-Infinity;const win=bankroll+stake*otherPool/(ownPool+stake),lose=bankroll-stake;return p*Math.log(win/bankroll)+(1-p)*Math.log(lose/bankroll)}
function fullKellyStake(bankroll,p,ownPool,otherPool){let lo=0,hi=bankroll*.999999;for(let i=0;i<100;i++){const a=lo+(hi-lo)/3,b=hi-(hi-lo)/3;if(growthFor(a,bankroll,p,ownPool,otherPool)<growthFor(b,bankroll,p,ownPool,otherPool))lo=a;else hi=b}const stake=(lo+hi)/2;return growthFor(stake,bankroll,p,ownPool,otherPool)>1e-12?stake:0}
const fmt=n=>Math.round(n).toLocaleString();
function updateKelly(){const total=Math.max(100,+$('#poolSize').value||100),marketBlue=Math.max(.01,Math.min(.99,(+$('#marketOdds').value||50)/100)),blue=total*marketBlue,red=total-blue,bankroll=Math.max(1,+$('#bankroll').value||1),beliefBlue=Math.max(.000001,Math.min(.999999,(+$('#belief').value||0)/100)),fraction=+$('#kellyFraction').value;$('#poolSizeOut').value=fmt(total);$('#marketOddsOut').value=`${(marketBlue*100).toFixed(1)}%`;$('#beliefOut').value=`${(beliefBlue*100).toFixed(1)}%`;$('#redPool').textContent=`${fmt(red)} in pool`;$('#bluePool').textContent=`${fmt(blue)} in pool`;$('#redOdds').textContent=`${(1+blue/red).toFixed(2)}× return`;$('#blueOdds').textContent=`${(1+red/blue).toFixed(2)}× return`;$('#totalPool').textContent=fmt(total);$('#marketBlue').textContent=`${(marketBlue*100).toFixed(1)}%`;$('#redBelief').value=`${((1-beliefBlue)*100).toFixed(1)}%`;const edge=(beliefBlue-marketBlue)*100;$('#beliefEdge').textContent=`${edge>=0?'+':''}${edge.toFixed(1)} pts`;const blueFull=fullKellyStake(bankroll,beliefBlue,blue,red),redFull=fullKellyStake(bankroll,1-beliefBlue,red,blue),blueGrowth=growthFor(blueFull,bankroll,beliefBlue,blue,red),redGrowth=growthFor(redFull,bankroll,1-beliefBlue,red,blue),side=blueGrowth>=redGrowth?'blue':'red',full=side==='blue'?blueFull:redFull,p=side==='blue'?beliefBlue:1-beliefBlue,own=side==='blue'?blue:red,other=side==='blue'?red:blue,stake=full*fraction,profit=stake?stake*other/(own+stake):0,ev=p*profit-(1-p)*stake,winBank=bankroll+profit,loseBank=bankroll-stake,expected=bankroll+ev,riskPct=stake/bankroll*100;$('#betSide').textContent=stake?`${side.toUpperCase()} · ${side==='blue'?'Party wins':'Boss wins'}`:'No bet';$('#betSide').className=`bet-side-label ${stake?side:''}`;$('#betStake').textContent=`${fmt(stake)} points`;$('#betExplanation').textContent=stake?`${fraction===1?'Full':fraction===.75?'Three-quarter':fraction===.5?'Half':'Quarter'} Kelly risks ${riskPct.toFixed(1)}% of current points after accounting for the stake's dilution of ${side.toUpperCase()}'s payout.`:'Neither side has positive expected logarithmic growth at the entered belief and pool.';const risk=riskPct===0?'None':riskPct<5?'Low':riskPct<15?'Moderate':riskPct<30?'High':'Very high';$('#riskLabel').textContent=`${risk} · ${riskPct.toFixed(1)}%`;$('#riskBar').style.width=`${Math.min(100,riskPct)}%`;$('#riskBar').className=side;$('#expectedReturn').textContent=`${ev>=0?'+':''}${fmt(ev)} points`;$('#winBankroll').textContent=fmt(winBank);$('#loseBankroll').textContent=fmt(loseBank);$('#expectedBankroll').textContent=fmt(expected);$('#fullKelly').textContent=`${fmt(full)} points`;$('#rewardRisk').textContent=stake?`${(ev/stake*100).toFixed(1)}% EV`:'—'}
function setup(){return{encounter:$('#encounter').value,levels:Object.fromEntries($$('.level-number').map(x=>[x.dataset.person,+x.value])),current:Object.fromEntries(PARTY.map(p=>[p.id,{hp:+$(`.heart-number[data-person="${p.id}"]`).value,juice:+$(`.juice-number[data-person="${p.id}"]`).value}])),inventory:$('#inventory').value,headbutt:$('#headbutt').checked}}
function sync(){const s=setup(),n=+$('#trials').value;$('#run').textContent=`Run ${n.toLocaleString()} battles`;$('#resultTitle').textContent=ENCOUNTERS[s.encounter].name;$('#inventoryText').textContent=invText[s.inventory];$('#assumptions').innerHTML=assumptions[s.encounter].map(x=>`<li>${x}</li>`).join('')}
async function run(){const s=setup(),n=+$('#trials').value,seed=+$('#seed').value||1;sync();$('#run').disabled=true;$('#status').textContent=`Running ${(n*4).toLocaleString()} seeded battles…`;const started=performance.now();try{const results=await new Promise((resolve,reject)=>{if(!window.Worker){resolve(runAll(s,n,seed));return}const w=new Worker('./worker.js',{type:'module'});w.onmessage=e=>{resolve(e.data);w.terminate()};w.onerror=reject;w.postMessage({setup:s,trials:n,seed})});current=results;renderResults(results);renderBetReferences();$('#status').textContent=`Complete in ${Math.round(performance.now()-started)} ms. Reusing seed ${seed} reproduces this comparison.`}catch(e){$('#status').textContent=`Worker unavailable; running locally…`;current=runAll(s,n,seed);renderResults(current);renderBetReferences();$('#status').textContent=`Complete locally with seed ${seed}.`}finally{$('#run').disabled=false}}

$$('.nav').forEach(b=>b.onclick=()=>{$$('.nav,.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(`#${b.dataset.view}`).classList.add('active')});
$('#partyLevels').innerHTML=PARTY.map(p=>`<div class="party-state-row"><div class="level-row"><span>${p.name}</span><input class="level-range" data-person="${p.id}" type="range" min="1" max="50" value="${p.level}" aria-label="${p.name} level"><input class="level-number" data-person="${p.id}" type="number" min="1" max="50" value="${p.level}" aria-label="${p.name} level number"></div><div class="resource-row"><label>Heart <input class="heart-number" data-person="${p.id}" type="number" min="0" value="${p.hp}"></label><label>Juice <input class="juice-number" data-person="${p.id}" type="number" min="0" value="${p.juice}"></label></div></div>`).join('');
$$('.level-range').forEach(r=>r.oninput=()=>{const n=$(`.level-number[data-person="${r.dataset.person}"]`);n.value=r.value;sync()});
$$('.level-number').forEach(n=>n.oninput=()=>{n.value=Math.max(1,Math.min(50,+n.value||1));$(`.level-range[data-person="${n.dataset.person}"]`).value=n.value;sync()});
$$('.heart-number,.juice-number').forEach(n=>n.oninput=sync);
['encounter','trials','inventory','headbutt'].forEach(id=>$(`#${id}`).addEventListener('input',sync));$('#run').onclick=run;
['poolSize','marketOdds','bankroll','belief','kellyFraction'].forEach(id=>$(`#${id}`).addEventListener('input',updateKelly));

let statImageUrls=[];
function captureImages(files){const images=[...files].filter(file=>file.type.startsWith('image/'));if(!images.length)return;for(const url of statImageUrls)URL.revokeObjectURL(url);statImageUrls=images.map(URL.createObjectURL);$('#statPreviews').innerHTML=statImageUrls.map((url,i)=>`<figure><img src="${url}" alt="Stat screen ${i+1}"><figcaption>${images[i].name||`Pasted image ${i+1}`}</figcaption></figure>`).join('');$('#importer').classList.add('has-image');$('#status').textContent=`${images.length} stat screen${images.length===1?'':'s'} captured as one import batch. Review or enter values manually; model-assisted extraction will reconcile the screens when the backend is connected.`}
$('#statImage').onchange=e=>captureImages(e.target.files);document.addEventListener('paste',e=>{const files=[...e.clipboardData.files].filter(f=>f.type.startsWith('image/'));if(files.length)captureImages(files)});

let rolled=null,turnIndex=0,rolledTurns=[];
function renderScenario(){if(!rolled)return;const turn=rolledTurns[turnIndex],entries=rolled.trace.filter(x=>x.turn===turn),x=entries.at(-1),expected=['Omori','Aubrey','Kel','Hero'],partyActions=expected.map(name=>{const e=entries.find(a=>a.actor===name);const member=x.party.find(p=>p.name===name);return`<div class="action-row"><span>${name}</span><strong>${e?e.action:member?.hp<=0?'is Toast — no action':'has no action'}</strong></div>`}).join(''),enemyActions=entries.filter(e=>!expected.includes(e.actor)&&e.actor!=='Party').map(e=>`<div class="action-row enemy-action"><span>${e.actor}</span><strong>${e.action}</strong></div>`).join(''),release=entries.find(e=>e.actor==='Party'),party=x.party.map(p=>`<div><span>${p.name}</span><i><b style="width:${100*p.hp/p.max}%"></b></i><small>${p.hp}/${p.max} HP · ${p.juice} J</small></div>`).join(''),foes=x.enemies.map(e=>`<div><span>${e.name}</span><i class="foe"><b style="width:${100*e.hp/e.max}%"></b></i><small>${e.hp}/${e.max} HP</small></div>`).join('');$('#scenarioState').innerHTML=`<div class="turn-title"><strong>Turn ${turn}</strong><small>All actions together · ${x.energy} Energy at turn end</small></div><div class="turn-actions">${partyActions}${release?`<div class="action-row"><span>Party</span><strong>${release.action}</strong></div>`:''}${enemyActions}</div><div class="health-grid"><section><label>End-of-turn party</label>${party}</section><section><label>End-of-turn enemy</label>${foes}</section></div>`;$('#scenarioProgress').textContent=`Turn ${turnIndex+1} of ${rolledTurns.length} · ${rolled.win?'Victory':'Defeat'} on turn ${rolled.turns}`;$('#nextAction').disabled=turnIndex>=rolledTurns.length-1}
$('#rollScenario').onclick=()=>{rolled=rollScenario(setup(),$('#scenarioPolicy').value,+$('#scenarioSeed').value||1);rolledTurns=[...new Set(rolled.trace.map(x=>x.turn))];turnIndex=0;renderScenario()};$('#nextAction').onclick=()=>{if(rolled&&turnIndex<rolledTurns.length-1){turnIndex++;renderScenario()}};

$('#profilePrompt').value='They understand the effects of each emotion, but not which emotion beats which or the advanced emotion tiers. They ignore speed order and Juice, focus one target, and race the enemy. They are careful during boss fights and heal frequently, using Cook around 60% Heart and allowing snacks around 35%. They still use Life Jam only when more than one person is Toast. During bosses they save Energy for Omori\'s Release Energy and usually avoid ordinary follow-ups while saving. Omori uses Stab frequently while he has enough Juice. Aubrey uses Headbutt frequently when she has enough Heart for the recoil. They repeat familiar actions and enter bosses immediately.';
$('#interpretProfile').onclick=async()=>{const button=$('#interpretProfile'),status=$('#profileStatus');button.disabled=true;status.textContent='Asking GPT-5.6 Luna for a structured profile patch…';try{const response=await fetch('/api/calibrate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({model:$('#profileModel').value,reasoning_effort:$('#profileEffort').value,description:$('#profilePrompt').value,current_profile:Object.fromEntries(dims)})});if(!response.ok)throw new Error(response.status===404?'The model route is not connected in this static prototype.':'The model route returned an error.');const patch=await response.json();$('#profilePatch').innerHTML=`<pre>${JSON.stringify(patch,null,2)}</pre><button id="applyProfile" class="primary">Apply reviewed patch</button>`;status.textContent='Review the proposed changes and confidence values before applying.'}catch(e){status.textContent=e.message+' The saved Someone v1 baseline remains active.';$('#profilePatch').innerHTML='<span>Model connection required. The prompt and review flow are ready; no profile values were changed.</span>'}finally{button.disabled=false}};
const actions=['Attack focused target','Use Run ’n Gun','Use a snack','Guard / conserve','Pass to Aubrey','Change emotion'];$('#actuals').innerHTML=actions.map(x=>`<button>${x}</button>`).join('');$$('#actuals button').forEach(b=>b.onclick=()=>{const match=b.textContent.includes('Attack');$('#calibrationNote').textContent=match?'Matches the prediction. Repeated matches would slightly strengthen damage urgency and familiar-action repetition.':`Observed: ${b.textContent}. This would become one calibration row; no automatic profile update is applied yet.`;localStorage.setItem('omori-last-observation',JSON.stringify({action:b.textContent,at:new Date().toISOString()}))});

$('#partyTable').innerHTML=`<table><thead><tr><th>Name</th><th>Lv</th><th>HP</th><th>Juice</th><th>ATK</th><th>DEF</th><th>SPD</th></tr></thead><tbody>${PARTY.map(p=>`<tr><td>${p.name}</td><td>${p.level}</td><td>${p.hp}/${p.maxHp}</td><td>${p.juice}/${p.maxJuice}</td><td>${p.atk}</td><td>${p.def}</td><td>${p.spd}</td></tr>`).join('')}</tbody></table><p class="equipment-list">${PARTY.map(p=>`${p.name}: ${p.weapon} · ${p.charm}`).join('<br>')}</p>`;
const enemyRows=[['Space Ex-Boyfriend',1350,15,16,25],['Download Window',600,10,5,1],['Space Bunny',105,12,7,10]];$('#enemyTable').innerHTML=`<table><thead><tr><th>Name</th><th>HP</th><th>ATK</th><th>DEF</th><th>SPD</th></tr></thead><tbody>${enemyRows.map(e=>`<tr><td>${e[0]}</td><td>${e[1]}</td><td>${e[2]}</td><td>${e[3]}</td><td>${e[4]}</td></tr>`).join('')}</tbody></table>`;

function registerTools(){const c=document.modelContext;if(!c?.registerTool)return;const add=t=>Promise.resolve(c.registerTool(t)).catch(()=>{});add({name:'configure_battle',title:'Configure battle',description:'Set the encounter, trial count, individual party levels, inventory, and Headbutt availability.',inputSchema:{type:'object',properties:{encounter:{type:'string',enum:Object.keys(ENCOUNTERS)},trials:{type:'integer',enum:[1000,5000,10000]},levels:{type:'object',properties:{omori:{type:'integer',minimum:1,maximum:50},aubrey:{type:'integer',minimum:1,maximum:50},kel:{type:'integer',minimum:1,maximum:50},hero:{type:'integer',minimum:1,maximum:50}},additionalProperties:false},inventory:{type:'string',enum:['standard','lean','none']},headbutt:{type:'boolean'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async x=>{if(x.encounter)$('#encounter').value=x.encounter;if(x.trials)$('#trials').value=x.trials;if(x.levels)for(const[id,v]of Object.entries(x.levels)){const n=$(`.level-number[data-person="${id}"]`),r=$(`.level-range[data-person="${id}"]`);if(n&&r)n.value=r.value=v}if(x.inventory)$('#inventory').value=x.inventory;if(typeof x.headbutt==='boolean')$('#headbutt').checked=x.headbutt;sync();return setup()}});add({name:'run_battle_simulation',title:'Run battle simulation',description:'Run all four visible decision policies with the current battle setup.',inputSchema:{type:'object',properties:{seed:{type:'integer',minimum:1}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async x=>{if(x.seed)$('#seed').value=x.seed;await run();return current}})}
sync();updateKelly();renderBetReferences();renderResults([{key:'suboptimal',name:'Suboptimal',rate:0,ci:[0,0],medianTurns:'—',avgSurvivors:0,wins:0,trials:0},{key:'decent',name:'Decent',rate:0,ci:[0,0],medianTurns:'—',avgSurvivors:0,wins:0,trials:0},{key:'best',name:'Best found',rate:0,ci:[0,0],medianTurns:'—',avgSurvivors:0,wins:0,trials:0},{key:'custom',name:'Someone',rate:0,ci:[0,0],medianTurns:'—',avgSurvivors:0,wins:0,trials:0}]);registerTools();run();
